cards.solution:
const harga = { kopi: 18000, teh: 12000, roti: 15000 };
function totalBelanja(keranjang, harga) {
  let total = 0;
  for (const [nama, jumlah] of Object.entries(keranjang)) {
    total += harga[nama] * jumlah;
  }
  return total;
}
console.log(totalBelanja({ kopi: 2, roti: 1 }, harga));
console.log(totalBelanja({}, harga));
